using StreamHash.Core.Testing;
using Xunit;

namespace StreamHash.Core.Tests.ReferenceData;

/// <summary>
/// Tests that verify StreamHash native implementations against reference hash values.
/// </summary>
/// <remarks>
/// These tests verify that Groestl and JH implementations produce correct output
/// by comparing against values generated by BouncyCastle and other reference implementations.
/// </remarks>
public class ReferenceHashVerificationTests {
	private static string ToHex(byte[] bytes) => Convert.ToHexStringLower(bytes);

	// ============================================================================
	// Groestl-256 Tests
	// ============================================================================

	[Fact]
	public void Groestl256_64KB_MatchesReference() {
		using var hasher = new Groestl256();
		hasher.Update(TestDataGenerator.File64KB);
		var result = ToHex(hasher.FinalizeBytes());
		Assert.Equal(ReferenceHashValues.KB64.Groestl256, result);
	}

