	// ============================================================================
	// Streaming Verification Tests (multiple Update calls)
	// ============================================================================

	[Fact]
	public void Groestl256_StreamingUpdate_MatchesReference() {
		var data = TestDataGenerator.File64KB;
		using var hasher = new Groestl256();

		// Feed data in chunks of varying sizes
		int offset = 0;
		int[] chunkSizes = [1, 7, 64, 128, 1000, 63, 127, 1];
		int chunkIndex = 0;

		while (offset < data.Length) {
			int chunkSize = Math.Min(chunkSizes[chunkIndex % chunkSizes.Length], data.Length - offset);
			hasher.Update(data.AsSpan(offset, chunkSize));
			offset += chunkSize;
			chunkIndex++;
		}

		var result = ToHex(hasher.FinalizeBytes());
		Assert.Equal(ReferenceHashValues.KB64.Groestl256, result);
	}

