	}

	// ============================================================================
	// Reset Tests
	// ============================================================================

	[Fact]
	public void Groestl256_Reset_ProducesSameResult() {
		using var hasher = new Groestl256();

		// First hash
		hasher.Update(TestDataGenerator.File64KB);
		var result1 = ToHex(hasher.FinalizeBytes());

		// Reset and hash again
		hasher.Reset();
		hasher.Update(TestDataGenerator.File64KB);
		var result2 = ToHex(hasher.FinalizeBytes());

		Assert.Equal(result1, result2);
		Assert.Equal(ReferenceHashValues.KB64.Groestl256, result1);
	}

	[Fact]
	public void JH256_Reset_ProducesSameResult() {
		using var hasher = new JH256();

		// First hash
		hasher.Update(TestDataGenerator.File64KB);
		var result1 = ToHex(hasher.FinalizeBytes());

		// Reset and hash again
		hasher.Reset();
		hasher.Update(TestDataGenerator.File64KB);
		var result2 = ToHex(hasher.FinalizeBytes());

		Assert.Equal(result1, result2);
		Assert.Equal(ReferenceHashValues.KB64.JH256, result1);
	}
